  "supportive_card_ids": ["C01", "C05", "C10", "C17", "C32", "C37", "C38", "C41", "C42", "C69", "C78", "C79"],
  "contradictory_card_ids": [],
  "prediction_basis_card_ids": ["C01", "C05", "C10", "C17", "C32", "C37", "C69", "C78", "C79"],
  "claims": [
    {
      "claim": "Query is a permanently charged quaternary ammonium tropane ester (butylscopolamine-like); the most transferable direct reference, umeclidinium, is also a quaternary ammonium antimuscarinic with negligible oral bioavailability and ≤12% systemic availability from oral/inhaled routes, supporting F <20%.",
      "card_ids": ["C01", "C05", "C10", "C17"]
    },
    {
      "claim": "Oral-exposure records for other quaternary ammonium antimuscarinics show very low plasma concentrations after oral dosing (trospium 60 mg XR Cmax ~1.5 ng/mL; glycopyrronium 2 mg Cmax 318 pg/mL), consistent with poor oral absorption; repeated trospium records are not independent votes.",
      "card_ids": ["C32", "C37", "C38", "C41", "C42"]
    },
    {
      "claim": "L5 gut-wall/intestinal records are mechanistically mixed: OCTN2 uptake for ipratropium/tiotropium and concentration-dependent trospium jejunal permeation indicate some carrier-mediated absorptive capacity, but these same compounds have low oral bioavailability; efflux records illustrate gut-wall efflux as a presystemic loss mechanism. Mechanism alone does not establish F ≥20%.",
      "card_ids": ["C56", "C58", "C60", "C63", "C64", "C65", "C66", "C67"]
    },
    {
      "claim": "L6 ipratropium records predict moderate hepatic clearance (9.6–12.4 ml/min/kg) with measurable hepatocyte uptake, adding hepatic first-pass as a presystemic loss mechanism for a close quaternary ammonium tropane analog; atropine's low human intrinsic clearance (2.59 µL/min/10^6 cells) is less transferable because atropine is tertiary, and the low prediction rests primarily on poor absorption.",
      "card_ids": ["C69", "C75", "C78", "C79"]
    },
    {
      "claim": "L6 microsomal intrinsic-clearance records for MEHP and FTY720-Mitoxy are structurally unrelated to the query and do not bear on its oral bioavailability.",
      "card_ids": ["C71", "C72", "C73"]
    },
    {
      "claim": "No query-specific direct oral bioavailability measurement exists; the low prediction rests on transferable direct low-F evidence and coherent absorption behavior, not on generic descriptor liabilities alone.",
      "card_ids": ["C01", "C05", "C10", "C17", "C32", "C37"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C68", "C69", "C70", "C71", "C72", "C73", "C74", "C75", "C76", "C77", "C78", "C79"]
    }
  ],
  "evidence_gaps": [
    "No direct experimental oral bioavailability measurement exists for the query molecule itself.",
    "No query-specific permeability, efflux, intestinal-metabolism, or hepatic-clearance data are supplied; transfer from umeclidinium/ipratropium/tiotropium/trospium is structural/class analogy.",
    "L3 oral-exposure records lack IV comparators and therefore cannot directly quantify absolute oral bioavailability.",
    "L4 records are solubility measurements in surfactant vehicles for fexofenadine/fenoprofen, not query-specific intestinal absorption or permeability.",
    "Query formulation and prandial state are unspecified.",
    "L6 hepatic-clearance records are in vitro/IVIVE for ipratropium/atropine and unrelated compounds (MEHP, FTY720-Mitoxy); atropine's low human intrinsic clearance is less transferable to the quaternary query."
  ],
  "decision_summary": "Prediction remains low and is strengthened. The query is a permanently charged quaternary ammonium tropane ester; transferable direct low-F evidence from umeclidinium and low oral-exposure records for trospium/glycopyrronium support F <20%. L6 ipratropium hepatic-clearance predictions add a hepatic first-pass mechanism, while atropine's low human intrinsic clearance is less transferable; no direct query-specific F ≥20% evidence appears."
}

